export type AccountBankCreateParams = {
  /**
   * The BIC (Business Identifier Code) of your bank.
   * Max length: 11.
   */
  bic: string;
  /**
   * The IBAN (International Bank Account Number).
   * Max length: 32.
   */
  iban: string;
  /**
   * The name of the bank account. This can contain localized text. To add
   * values in multiple languages, use the XML format like this:
   * <values><de>German text</de><en>English text</en></values>
   * Max length: 100.
   */
  name: string;
  /**
   * The type of bank account, i.e. what is the bank account used for? Possible
   * values: DEFAULT, ORDER, SALARY, HISTORICAL, OTHER.
   */
  type: "DEFAULT" | "ORDER" | "SALARY" | "HISTORICAL" | "OTHER";
  /** The ID of the financial account linked to this bank account. See Account . */
  accountId?: number | null;
  /**
   * List of files to attach. This is a JSON array [{...},{...},...] with the
   * following parameters:
   * Serialized to JSON before sending.
   */
  attachments?: readonly ({
    fileId?: number;
  })[] | null;
  /**
   * The ID of the currency. Leave empty to use the default currency. See
   * Currency .
   */
  currencyId?: number | null;
  /**
   * Mark this bank account as inactive. Inactive bank accounts are greyed out
   * in the list and are no longer suggested by the app. Possible values: true,
   * false.
   */
  isInactive?: boolean | null;
  /**
   * Some optional notes. This can contain limited HTML for styling. Allowed
   * tags: a, p, div, h1, h2, h3, h4, h5, h6, ul, ol, li, blockquote, b, i, s,
   * u, o, sup, sub, ins, del, strong, strike, tt, code, big, small, br, span,
   * em. Allowed inline CSS rules: background, background-color, color, font,
   * font-size, font-weight, font-style, text-align, text-indent,
   * text-decoration.
   */
  notes?: string | null;
  /**
   * The first few digits of the Swiss QR reference (0 by default). This is
   * specific to Switzerland.
   * Max length: 8.
   */
  qrFirstDigits?: number | null;
  /**
   * The QR-IBAN, which is an IBAN especially for QR invoices (former ESR).
   * This is specific to Switzerland.
   * Max length: 32.
   */
  qrIban?: string | null;
  /**
   * An optional URL for the bank's e-banking portal.
   * Max length: 255.
   */
  url?: string | null;
};

