export type TaxCreateParams = {
  /**
   * A short code to identify the tax code.
   * Max length: 32.
   */
  code: string;
  /** The components of the tax code, up to two possible. */
  components: string;
  /**
   * Tax rates that are valid from a given date. Add a new tax rate here if the
   * official tax rate changes. Exactly one tax rate must exist without a valid
   * from date.
   */
  rates: string;
  /**
   * A description for the tax code. This can contain localized text. To add
   * values in multiple languages, use the XML format like this:
   * <values><de>German text</de><en>English text</en></values>
   * Max length: 100.
   */
  description?: string | null;
  /**
   * The name for the tax code displayed on documents (seen by customers). If
   * isDisplayTaxRate is set, this name doesn't have to include the tax rate
   * percentage, it will be automatically appended. This can contain localized
   * text. To add values in multiple languages, use the XML format like this:
   * <values><de>German text</de><en>English text</en></values>
   * Max length: 50.
   */
  documentName?: string | null;
  /**
   * Whether to automatically append the current tax rate to the document name
   * (see documentName ) or not. Possible values: true, false.
   */
  isDisplayTaxRate?: boolean | null;
  /**
   * Mark the tax code as inactive. This means that the tax code is greyed out
   * and no longer suggested. Tax codes already in use cannot be deleted, but
   * you can always set them as inactive. Defaults to false. Possible values:
   * true, false.
   * Defaults to `false`.
   */
  isInactive?: boolean | null;
};

